    "drawingSvg": "<svg viewBox=\"0 0 240 145\" class=\"w-full h-full\"><defs><marker id=\"arr-20905\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto-start-reverse\"><path d=\"M 0 1.5 L 8 5 L 0 8.5 z\" fill=\"#000000\"/></marker></defs><rect x=\"14\" y=\"14\" width=\"34\" height=\"34\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.1\"/><text x=\"31.0\" y=\"34.0\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">e^\u03bb</text><rect x=\"48\" y=\"14\" width=\"34\" height=\"34\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.1\"/><text x=\"65.0\" y=\"34.0\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">e^\u03bb</text><rect x=\"82\" y=\"14\" width=\"34\" height=\"34\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.1\"/><text x=\"99.0\" y=\"34.0\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">e^\u03bb/2</text><rect x=\"14\" y=\"48\" width=\"34\" height=\"34\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.1\"/><text x=\"31.0\" y=\"68.0\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\"></text><rect x=\"48\" y=\"48\" width=\"34\" height=\"34\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.1\"/><text x=\"65.0\" y=\"68.0\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">e^\u03bb</text><rect x=\"82\" y=\"48\" width=\"34\" height=\"34\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.1\"/><text x=\"99.0\" y=\"68.0\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">e^\u03bb</text><rect x=\"14\" y=\"82\" width=\"34\" height=\"34\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.1\"/><text x=\"31.0\" y=\"102.0\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\"></text><rect x=\"48\" y=\"82\" width=\"34\" height=\"34\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.1\"/><text x=\"65.0\" y=\"102.0\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\"></text><rect x=\"82\" y=\"82\" width=\"34\" height=\"34\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.1\"/><text x=\"99.0\" y=\"102.0\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">e^\u03bb</text><text x=\"62\" y=\"126\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#000000\">e^{J\u2083(\u03bb)} = e^\u03bb (I + N + N\u00b2/2)</text><text x=\"160\" y=\"28\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"bold\" text-anchor=\"start\" fill=\"#000000\">f(J_k(\u03bb)) =</text><text x=\"160\" y=\"42\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"start\" fill=\"#000000\">\u03a3_j f^{(j)}(\u03bb)/j! \u00b7 N^j</text><text x=\"160\" y=\"64\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"start\" fill=\"#000000\">finite sum: N^k = 0</text><text x=\"160\" y=\"84\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"start\" fill=\"#000000\">A = PJP\u207b\u00b9 \u21d2</text><text x=\"160\" y=\"98\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"bold\" text-anchor=\"start\" fill=\"#000000\">f(A) = P f(J) P\u207b\u00b9</text><text x=\"160\" y=\"118\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"start\" fill=\"#000000\">e^{tA} solves x\u2032 = Ax</text></svg>",
